from __future__ import annotations
import ast, hashlib, subprocess, sys
from pathlib import Path

def locate_repository():
    here = Path(__file__).resolve().parent
    candidates = [Path.cwd().resolve(), here]
    for base in tuple(candidates):
        candidates.extend(base.parents)
    for root in candidates:
        package = root / "qseries_v2" / "oracle_terminal"
        p38 = package / "oracle_real_intelligence_response_validation_gate.py"
        t38 = root / "test_oit_038_oracle_real_intelligence_response_validation_gate.py"
        p37 = package / "oracle_authorized_real_intelligence_read_invocation_execution_gate.py"
        if p38.is_file() and t38.is_file() and p37.is_file():
            return root.resolve()
    raise SystemExit("[ERROR] Could not locate current Q Series repository.")

